      cr.initFromPage(COUNT, bytes1.toInputStream());
      for (float i = 0; i < COUNT; i++) {
        float back = cr.readFloat();
        assertEquals(i % 50, back, 0.0f);
      }

      cr.initFromPage(COUNT2, bytes2.toInputStream());
      for (float i = COUNT2; i > 0; i--) {
        float back = cr.readFloat();
        assertEquals(i % 50, back, 0.0f);
      }
    }
